CREATE OR REPLACE FUNCTION public.admin_delete_profile(p_role text, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  roles text[];
  target_table text;
begin
  if public.app_role() <> 'admin' then
    raise exception 'Administrator access required';
  end if;
  if p_role = 'student' then
    roles := array['student','parent'];
    target_table := 'students';
  elsif p_role = 'teacher' then
    roles := array['teacher'];
    target_table := 'teachers';
  else
    raise exception 'Invalid role';
  end if;

  execute format('delete from public.users where ref = $1 and role = any($2)', target_table) using p_ref, roles;
  execute format('delete from public.%I where id = $1', target_table) using p_ref;
  return jsonb_build_object('deleted', true, 'role', p_role, 'ref', p_ref);
end;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_web_push_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg record;
begin
  select internal_secret into cfg from public.push_config where id=1;
  if cfg.internal_secret is null then return new; end if;
  perform net.http_post(
    url:='https://efnxjfzyqbdulpjhffsm.supabase.co/functions/v1/web-push',
    headers:=jsonb_build_object('Content-Type','application/json','x-lg-push-secret',cfg.internal_secret),
    body:=jsonb_build_object('action','dispatch','notification_id',new.id)::jsonb,
    timeout_milliseconds:=5000
  );
  return new;
exception when others then
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.emit_announcement_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_audience text := lower(trim(coalesce(new.target,'all')));
  refs text[];
  r record;
  role_name text;
begin
  if v_audience in ('all','everyone','*') then
    for r in select id from auth.users where (raw_app_meta_data->>'role') in ('student','parent','teacher') loop
      perform public.notification_insert_for_auth(r.id,new.title,coalesce(new.desc,''),'announcement');
    end loop;
  elsif v_audience in ('students','student','parents','parent','teachers','teacher') then
    role_name := case when v_audience like 'student%' then 'student' when v_audience like 'parent%' then 'parent' else 'teacher' end;
    for r in select id from auth.users where (raw_app_meta_data->>'role')=role_name loop
      perform public.notification_insert_for_auth(r.id,new.title,coalesce(new.desc,''),'announcement');
    end loop;
  else
    if v_audience like 'batch:%' then v_audience := substr(v_audience,7); end if;
    refs := public.notification_refs_for_batch(v_audience);
    perform public.notification_insert_for_refs(refs,new.title,coalesce(new.desc,''),'announcement');
    for r in select u.id from auth.users u where (u.raw_app_meta_data->>'role')='teacher' and exists(select 1 from public.timetable_entries te where te.batch_id=v_audience and te.teacher_id=(u.raw_app_meta_data->>'ref') and te.status='active') loop
      perform public.notification_insert_for_auth(r.id,new.title,coalesce(new.desc,''),'announcement');
    end loop;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.emit_attendance_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; sid text := new.sid::text;
begin
  for r in select distinct u.id from auth.users u where u.raw_app_meta_data->>'ref'=sid and u.raw_app_meta_data->>'role'='student' loop
    perform public.notification_insert_for_auth(r.id,'Attendance updated','Your attendance for '||coalesce(new.date,'today')||' is marked '||coalesce(new.status,'updated')||'.','attendance');
  end loop;
  for r in select distinct psl.parent_auth_id from public.parent_student_links psl where psl.student_id=sid and psl.status='active' loop
    perform public.notification_insert_for_auth(r.parent_auth_id,'Attendance updated','Attendance for your linked student on '||coalesce(new.date,'today')||' is '||coalesce(new.status,'updated')||'.','attendance');
  end loop;
  return new;
end; $function$

