CREATE OR REPLACE FUNCTION public.emit_timetable_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare refs text[]; r record; changed boolean := (tg_op='INSERT');
begin
  if tg_op='UPDATE' then changed := (old.batch_id is distinct from new.batch_id or old.teacher_id is distinct from new.teacher_id or old.subject_name is distinct from new.subject_name or old.day_of_week is distinct from new.day_of_week or old.start_time is distinct from new.start_time or old.end_time is distinct from new.end_time or old.room_id is distinct from new.room_id or old.status is distinct from new.status); end if;
  if not changed or coalesce(new.status,'active')<>'active' then return new; end if;
  refs := public.notification_refs_for_batch(new.batch_id);
  perform public.notification_insert_for_refs(refs,'Timetable updated',coalesce(new.subject_name,'Class')||' timetable has been updated.','timetable');
  for r in select u.id from auth.users u where u.raw_app_meta_data->>'role'='teacher' and u.raw_app_meta_data->>'ref'=new.teacher_id loop
    perform public.notification_insert_for_auth(r.id,'Timetable updated',coalesce(new.subject_name,'Class')||' timetable has been updated.','timetable');
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.homework_row_readable(p_id text, p_batch_id text, p_cls text, p_sec text, p_tid text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if public.app_role() = 'admin' then
    return true;
  end if;

  if public.app_role() = 'teacher' then
    return p_tid is not null and p_tid = public.current_ref();
  end if;

  if public.app_role() = 'parent' then
    if p_batch_id is not null then
      return public.parent_can_access_batch(p_batch_id);
    end if;

    return exists (
      select 1
      from public.parent_student_links psl
      join public.students s on s.id = psl.student_id
      where psl.parent_auth_id = auth.uid()
        and psl.status = 'active'
        and coalesce(s.status, 'active') = 'active'
        and s.cls = p_cls
        and (p_sec is null or p_sec = '' or s.sec = p_sec)
    );
  end if;

  if public.app_role() = 'student' then
    if p_batch_id is not null then
      return public.student_can_access_batch(p_batch_id, public.current_ref());
    end if;

    return exists (
      select 1
      from public.students s
      where s.id = public.current_ref()
        and s.cls = p_cls
        and (p_sec is null or p_sec = '' or s.sec = p_sec)
    );
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.homework_storage_readable(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare h record;
begin
  select id,batch_id,cls,sec,tid into h from public.homework where storage_path=p_path limit 1;
  if not found then return false; end if;
  if public.app_role()='admin' then return true; end if;
  if public.app_role()='teacher' then
    return h.tid=public.current_ref() or (h.batch_id is not null and public.teacher_can_access_batch(h.batch_id,public.current_ref()));
  end if;
  if public.app_role()='student' then
    return public.student_can_access_batch(h.batch_id,public.current_ref());
  end if;
  if public.app_role()='parent' then
    return exists(select 1 from public.parent_student_links psl join public.batch_students bs on bs.student_id=psl.student_id and bs.batch_id=h.batch_id where psl.parent_auth_id=auth.uid() and psl.status='active' and bs.status='active' and bs.left_at is null);
  end if;
  return false;
end; $function$

