CREATE OR REPLACE FUNCTION public.notify_attendance_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  student_user_id text;
  parent_user_id text;
  status_label text;
  notification_title text;
  notification_desc text;
begin
  status_label := initcap(coalesce(new.status, 'updated'));
  notification_title := 'Attendance updated';
  notification_desc := 'Attendance for ' || coalesce(new.date::text, 'today') || ': ' || status_label || '.';
  select u.id::text into student_user_id from public.users u where u.role='student' and u.ref=new.sid::text limit 1;
  if student_user_id is not null then
    insert into public.notifications (id, uid, title, "desc", time, type, read) values (gen_random_uuid()::text, student_user_id, notification_title, notification_desc, now()::text, 'attendance', false) on conflict do nothing;
  end if;
  select u.id::text into parent_user_id from public.parent_student_links psl join public.users u on u.role='parent' and u.auth_id::text=psl.parent_auth_id::text where psl.student_id::text=new.sid::text and psl.status='active' limit 1;
  if parent_user_id is not null then
    insert into public.notifications (id, uid, title, "desc", time, type, read) values (gen_random_uuid()::text, parent_user_id, notification_title, notification_desc, now()::text, 'attendance', false) on conflict do nothing;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.notify_parents_of_test_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  test_row public.tests%rowtype;
  student_name text;
  pct numeric;
  parent_row record;
  notification_id text;
  notification_desc text;
begin
  if tg_op = 'UPDATE' and old.marks is not distinct from new.marks and old.remarks is not distinct from new.remarks then
    return new;
  end if;

  select * into test_row from public.tests where id = new.test_id limit 1;
  select name into student_name from public.students where id = new.student_id limit 1;
  pct := case when coalesce(test_row.total_marks,0) > 0 then round((new.marks / test_row.total_marks) * 100, 2) else null end;
  notification_desc := 'Result published for ' || coalesce(student_name,'your student') || ': ' || coalesce(test_row.subject,'Test') || ' — ' || new.marks::text || '/' || coalesce(test_row.total_marks,0)::text || ' (' || coalesce(pct::text,'—') || '%).' || case when nullif(trim(coalesce(new.remarks,'')),'') is not null then ' Remarks: ' || trim(new.remarks) else '' end;

  for parent_row in
    select distinct parent_auth_id
    from public.parent_student_links
    where student_id = new.student_id
      and lower(coalesce(status,'')) = 'active'
      and parent_auth_id is not null
  loop
    notification_id := 'result-' || new.id || '-' || parent_row.parent_auth_id::text;
    insert into public.notifications (id,title,"desc",time,type,read,uid,created_at)
    values (notification_id,'📊 Result Published: ' || coalesce(test_row.title, test_row.subject, 'Test'),notification_desc,to_char(now(),'DD Mon YYYY, HH12:MI AM'),'test_result',false,parent_row.parent_auth_id::text,now())
    on conflict (id) do update set title=excluded.title,"desc"=excluded."desc",time=excluded.time,read=false,created_at=excluded.created_at;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_test_to_batch_students()
