AS $function$
declare r record;
begin
  for r in select distinct u.auth_id, bs.student_id from public.batch_students bs join public.users u on u.ref=bs.student_id and u.role='student' and u.auth_id is not null where bs.batch_id=new.batch_id and bs.status='active' loop
