  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_batch_teacher_subject_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  matched_subject public.subjects%rowtype;
begin
  if new.subject_id is null then
    if nullif(trim(coalesce(new.subject_name, '')), '') is null then
      raise exception 'A teacher assignment requires a subject.' using errcode = '23502';
    end if;

    select * into matched_subject
    from public.subjects
    where lower(trim(name)) = lower(trim(new.subject_name))
    order by created_at nulls last, id
    limit 1;

    if matched_subject.id is null then
      raise exception 'Subject "%" does not exist. Create the subject first, then assign the teacher.', new.subject_name using errcode = '23503';
    end if;

    new.subject_id := matched_subject.id;
    new.subject_name := matched_subject.name;
  else
    select * into matched_subject
    from public.subjects
    where id = new.subject_id
    limit 1;

    if matched_subject.id is null then
      raise exception 'Subject ID "%" does not exist.', new.subject_id using errcode = '23503';
    end if;

    if nullif(trim(coalesce(new.subject_name, '')), '') is null then
      new.subject_name := matched_subject.name;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_admin_compat_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if TG_TABLE_NAME = 'students' then
    -- The students table uses lowercase parentname/parentphone columns.
    -- Do not reference the removed camelCase parentName/parentPhone columns.
    null;
  elsif TG_TABLE_NAME = 'batches' then
    if new.teacherids is null and new."teacherIds" is not null then new.teacherids := new."teacherIds"; end if;
    if new.studentids is null and new."studentIds" is not null then new.studentids := new."studentIds"; end if;
    if new."teacherIds" is null and new.teacherids is not null then new."teacherIds" := new.teacherids; end if;
    if new."studentIds" is null and new.studentids is not null then new."studentIds" := new.studentids; end if;
  elsif TG_TABLE_NAME = 'examschedule' then
    if new.starttime is null and new."startTime" is not null then new.starttime := new."startTime"; end if;
    if new.endtime is null and new."endTime" is not null then new.endtime := new."endTime"; end if;
    if new.totalmarks is null and new."totalMarks" is not null then new.totalmarks := new."totalMarks"; end if;
    if new."startTime" is null and new.starttime is not null then new."startTime" := new.starttime; end if;
    if new."endTime" is null and new.endtime is not null then new."endTime" := new.endtime; end if;
    if new."totalMarks" is null and new.totalmarks is not null then new."totalMarks" := new.totalmarks; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_approved_leave_to_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; existing_status text;
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    d := new.from_date;
    while d <= new.to_date loop
      if extract(isodow from d) between 1 and 6 then
        select status into existing_status from public.attendance where sid = new.student_id and date = d::text limit 1;
        if existing_status is null then
          insert into public.attendance(id, sid, date, status, by, leave_request_id) values (gen_random_uuid()::text, new.student_id, d::text, 'leave', 'system', new.id);
        elsif existing_status = 'leave' then
          update public.attendance set leave_request_id = new.id where sid = new.student_id and date = d::text and leave_request_id is null;
        end if;
      end if;
      d := d + 1;
    end loop;
  elsif old.status = 'approved' and new.status = 'cancelled' then
    delete from public.attendance where leave_request_id = new.id;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.sync_test_result_to_legacy_marks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.tests%rowtype;
begin
  if tg_op = 'DELETE' then delete from public.marks where id=old.id; return old; end if;
  select * into t from public.tests where id=new.test_id;
  if not found then return new; end if;
  insert into public.marks (id,sid,subject,exam,marks,total,date,tid,created_at)
  values (new.id,new.student_id,t.subject,t.title,new.marks,t.total_marks,t.test_date::text,null,new.created_at)
  on conflict (id) do update set sid=excluded.sid,subject=excluded.subject,exam=excluded.exam,marks=excluded.marks,total=excluded.total,date=excluded.date,created_at=excluded.created_at;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.sync_timetable_batch_teacher_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  subject_part text;
  matched_subject public.subjects%rowtype;
  assignment_status text;
begin
  assignment_status := case when new.status = 'active' then 'active' else 'inactive' end;
  for subject_part in
    select trim(value)
    from regexp_split_to_table(coalesce(new.subject_name, ''), '\\s*\\+\\s*') as value
    where trim(value) <> ''
  loop
    select * into matched_subject
    from public.subjects
    where lower(trim(name)) = lower(trim(subject_part))
    order by created_at nulls last, id
    limit 1;
    if matched_subject.id is not null then
      insert into public.batch_teachers(batch_id, teacher_id, subject_id, subject_name, status)
      values (new.batch_id, new.teacher_id, matched_subject.id, matched_subject.name, assignment_status)
      on conflict (batch_id, teacher_id, subject_id)
      do update set subject_name = excluded.subject_name, status = excluded.status;
    end if;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_teacher_account_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.role = 'teacher' then
    if new.ref is null then
      raise exception 'Teacher user record must reference a teacher profile';
    end if;
    if not exists (select 1 from public.teachers t where t.id = new.ref) then
      raise exception 'Teacher user record references a missing teacher profile';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_test_result_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total numeric;
  v_batch_id text;
  v_active boolean;
begin
  select total_marks, batch_id into v_total, v_batch_id from public.tests where id = new.test_id;
  if v_total is null then
    raise exception 'Test does not exist';
  end if;
  if new.marks is null or new.marks < 0 or new.marks > v_total then
    raise exception 'Marks must be between 0 and the test total marks';
  end if;
  select exists (
    select 1 from public.batch_students bs
    where bs.student_id = new.student_id
      and bs.batch_id = v_batch_id
      and bs.status = 'active'
      and bs.left_at is null
  ) into v_active;
  if not v_active then
    raise exception 'Student is not an active member of the test batch';
  end if;
  return new;
end;
$function$
